BEGIN TRANSACTION;
CREATE TABLE findings (
  finding_id TEXT PRIMARY KEY,
  source_url TEXT NOT NULL UNIQUE,
  run_id TEXT NOT NULL,
  first_run_id TEXT NOT NULL,
  date TEXT NOT NULL,
  captured_at TEXT NOT NULL,
  headline TEXT NOT NULL,
  category TEXT,
  tool_or_company TEXT,
  summary TEXT,
  at_home_use TEXT,
  source_name TEXT,
  source_tier TEXT,
  device_access_technical_barrier TEXT,
  priority TEXT NOT NULL,
  score REAL NOT NULL,
  score_breakdown TEXT,
  repeat_relevance_marker TEXT,
  status TEXT,
  notes TEXT
);
CREATE TABLE foundational_tools (
  tool_id TEXT PRIMARY KEY,
  date_added TEXT,
  tool_name TEXT NOT NULL,
  category TEXT,
  core_use_case TEXT,
  accessibility TEXT,
  why_foundational TEXT,
  status TEXT
);
CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE runs (
  run_id TEXT PRIMARY KEY,
  trigger TEXT NOT NULL,
  status TEXT NOT NULL,
  started_at TEXT NOT NULL,
  finished_at TEXT,
  run_date TEXT NOT NULL,
  time_range TEXT,
  summary TEXT,
  top_takeaway TEXT,
  num_findings INTEGER DEFAULT 0,
  num_updated INTEGER DEFAULT 0,
  num_watchlist_items INTEGER DEFAULT 0,
  report_name TEXT,
  sources_json TEXT
);
CREATE TABLE seen_items (
  url TEXT PRIMARY KEY,
  source_url TEXT NOT NULL,
  fingerprint TEXT,
  outcome TEXT NOT NULL,
  first_seen TEXT NOT NULL,
  last_seen TEXT NOT NULL
);
CREATE TABLE source_state (
  url TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  status TEXT,
  detail TEXT,
  last_checked TEXT,
  last_success TEXT,
  etag TEXT,
  last_modified TEXT,
  consecutive_failures INTEGER DEFAULT 0,
  circuit_open_until TEXT,
  items_seen INTEGER DEFAULT 0,
  items_emitted INTEGER DEFAULT 0
);
CREATE TABLE watchlist (
  watch_id TEXT PRIMARY KEY,
  source_url TEXT NOT NULL UNIQUE,
  run_id TEXT NOT NULL,
  date_added TEXT NOT NULL,
  item_trend TEXT NOT NULL,
  category TEXT,
  why_watched TEXT,
  what_needs_confirmation TEXT,
  source_lead TEXT,
  priority TEXT,
  status TEXT,
  last_reviewed TEXT,
  notes TEXT
);
CREATE INDEX idx_findings_run ON findings(run_id);
COMMIT;
